export function toPersonListElementProps(id, data, affiliationLabel, homeOrgId, orgDisplayLookup) {
    const fullName = (data.honorific ? `${data.honorific} ${data.name}` : data.name) || id;
    // When `affiliationLabel` is explicitly provided (e.g. the org detail
    // page passes the person's role at that org), the caller already
    // establishes the context — appending the home-org headline
    // duplicates or muddles the row. Otherwise resolve the canonical
    // "[Role] · [Org Name]" label via the shared helper so this matches
    // PersonCard chips and PersonDetail subtitles.
    let description;
    if (affiliationLabel) {
        description = affiliationLabel;
    }
    else {
        description = resolvePersonHeadline(data, {
            homeOrgId,
            orgDisplayLookup,
        }).label;
    }
    const imagePolicy = resolveImagePolicy(data.imagePolicy);
    return {
        title: fullName,
        description,
        href: `/people/${id}`,
        type: "people",
        logo: data.images?.avatar,
        imageAlt: fullName,
        logoBackdrop: imagePolicy.logoOrAvatarBackdropInList,
        featuredState: isFeaturedOnSite(data, getActiveSiteKey()) ? "featured" : "not-featured",
    };
}
export function toOrganizationListElementProps(id, data, roleLabel, isSelfLink = false, hrefOverride) {
    const title = data?.shortName || data?.name || id;
    const location = data?.location?.city || data?.location?.country
        ? [data?.location?.city, data?.location?.country]
            .filter(Boolean)
            .join(", ")
        : undefined;
    const parts = [roleLabel, location].filter(Boolean);
    const description = parts.length > 0 ? parts.join(" · ") : data?.description;
    const imagePolicy = resolveImagePolicy(data?.imagePolicy);
    // Link resolution precedence:
    //   1. explicit override (e.g. an external org website for an
    //      affiliation we don't track as a collection entry). An explicit
    //      empty string suppresses the link entirely — the row renders as
    //      static text. Distinguished from `undefined` (no override).
    //   2. self-link → site root
    //   3. real org entry → /organizations/<id>
    //   4. no resolvable target → empty string (renders as text)
    const href = hrefOverride !== undefined
        ? hrefOverride
        : isSelfLink
            ? "/"
            : data
                ? `/organizations/${id}`
                : "";
    return {
        title,
        description,
        href,
        type: "organizations",
        logo: resolveLogoAsset(data?.images),
        imageAlt: title,
        logoBackdrop: imagePolicy.logoOrAvatarBackdropInList,
        featuredState: isFeaturedOnSite(data, getActiveSiteKey()) ? "featured" : "not-featured",
    };
}
const PUBLICATION_KIND_LABELS = {
    paper: "Paper",
    preprint: "Preprint",
    thesis: "Thesis",
    report: "Report",
    article: "Article",
    essay: "Essay",
    whitepaper: "Whitepaper",
    dataset: "Dataset",
    benchmark: "Benchmark",
};
export function publicationKindLabel(kind) {
    if (!kind)
        return undefined;
    return PUBLICATION_KIND_LABELS[kind];
}
/**
 * Convert an `AwardCardData` to props for `ItemListElement`. Each
 * award has a simplified detail page at `/press/awards/<id>/` that
 * surfaces the full recipient list and links to the grantor's
 * announcement; the listing row links there. Callers that need a
 * different target (e.g. a card embedded in an unusual context) can
 * pass an `hrefOverride`.
 */
export function toAwardListElementProps(id, data, hrefOverride) {
    const title = data.title || id;
    const awardDate = data.awardDate ? new Date(data.awardDate) : undefined;
    const dateLabel = awardDate && !Number.isNaN(awardDate.getTime())
        ? awardDate.toLocaleDateString(undefined, {
            year: "numeric",
            month: "short",
        })
        : undefined;
    const grantor = data.grantingOrganizationName;
    const description = [grantor, dateLabel].filter(Boolean).join(" · ") || data.description;
    // Explicit empty-string override suppresses the link entirely
    // (renders as static text in `ItemListElement`). Distinguished from
    // `undefined`, which falls through to the default detail-page route.
    const href = hrefOverride !== undefined ? hrefOverride : `/press/awards/${id}`;
    return {
        title,
        description,
        href,
        type: "press",
        logo: data.images?.logo,
        imageAlt: title,
        featuredState: isFeaturedOnSite(data, getActiveSiteKey()) ? "featured" : "not-featured",
    };
}
