export function toPersonListData(source) {
    if (!source)
        return null;
    return isPersonEntryLike(source) ? source.data : source;
}
export function toPersonPopoverData(personEntry) {
    if (!personEntry?.data) {
        return null;
    }
    const { data } = personEntry;
    const avatar = data.images?.avatar;
    return {
        id: personEntry.id,
        name: data.name,
        honorific: data.honorific,
        pronouns: data.pronouns,
        title: data.title,
        bio: data.bio,
        expertise: data.expertise,
        links: data.links,
        images: avatar
            ? {
                avatar: {
                    src: avatar.src,
                    width: avatar.width,
                    height: avatar.height,
                    format: avatar.format ?? "unknown",
                },
            }
            : undefined,
    };
}
/**
 * Returns true when an affiliation is currently active — i.e. has no end date
 * or its end date is at/after the provided reference time.
 */
export function isCurrentAffiliation(affiliation, at = new Date()) {
    if (!affiliation.endDate)
        return true;
    const endDate = toDate(affiliation.endDate);
    return Boolean(endDate && endDate >= at);
}
/**
 * Picks the affiliation to surface for a given site. Resolution order:
 * 1. The affiliation matching `homeOrgId`, if present AND currently active.
 * 2. The first array entry that is currently active.
 * Returns `undefined` when no affiliation qualifies.
 */
export function getCurrentAffiliation(affiliations, homeOrgId, at = new Date()) {
    if (!affiliations?.length)
        return undefined;
    if (homeOrgId) {
        const homeAff = affiliations.find((aff) => aff.organizationId === homeOrgId);
        if (homeAff && isCurrentAffiliation(homeAff, at)) {
            return homeAff;
        }
    }
    return affiliations.find((aff) => isCurrentAffiliation(aff, at));
}
/**
 * Returns the headline role string to render as a person's subtitle on a
 * given site. Falls back through: current home-org role → first current
 * affiliation role → top-level `data.title`.
 */
export function getHeadlineRole(data, homeOrgId, at = new Date()) {
    return (getCurrentAffiliation(data.affiliations, homeOrgId, at)?.role ?? data.title);
}
/**
 * Builds a consistent "Role · Org Name" label (with optional department,
 * rendered as "Role, Department · Org Name") for use as the
 * `affiliationLabel` on `PersonListElement` across all rendering contexts —
 * press authors, organization key contacts, contributors lists, etc.
 *
 * All fields are optional; pieces that are missing or empty are skipped.
 * Returns `undefined` when nothing meaningful can be assembled.
 */
export function formatAffiliationLabel(input) {
    const rolePart = input.department
        ? input.role
            ? `${input.role}, ${input.department}`
            : input.department
        : input.role;
    const parts = [rolePart, input.organizationName].filter((s) => Boolean(s && s.trim()));
    return parts.length ? parts.join(" · ") : undefined;
}
/**
 * Single source of truth for "how should this person be labeled on this
 * site?". Selects the appropriate affiliation (home-org-first, then first
 * currently-active), resolves the org display name (explicit override
 * wins over collection lookup), and formats as `[Role] · [Org Name]`.
 *
 * Always renders the org when one is resolvable — even when the
 * affiliation matches `homeOrgId`. This is a deliberate consistency
 * choice: a person labeled "Executive Director · Semio Community" on the
 * semio-community site reads the same as on quori or vizij, and avoids
 * the implicit-org ambiguity that produced the original bug (Saad
 * Elbeleidy's hero subtitle reading "Executive Director" on the
 * semio-community site, implying a semio-community role).
 *
 * Falls through to `data.title` only when no affiliations exist at all
 * (legacy people records).
 */
export function resolvePersonHeadline(data, ctx = {}) {
    const affiliation = getCurrentAffiliation(data.affiliations, ctx.homeOrgId, ctx.at);
    if (!affiliation) {
        return {
            role: data.title,
            label: data.title,
        };
    }
    // Display-name precedence: explicit override on the affiliation >
    // org-collection lookup > raw id (last resort, surfaces missing
    // lookup data as a visible-but-functional fallback).
    const organizationName = affiliation.organizationName ??
        ctx.orgDisplayLookup?.(affiliation.organizationId) ??
        affiliation.organizationId;
    return {
        affiliation,
        organizationName,
        role: affiliation.role,
        label: formatAffiliationLabel({
            role: affiliation.role,
            department: affiliation.department,
            organizationName,
        }),
    };
}
/**
 * Builds an `OrgDisplayLookup` from a loaded `organizations` collection.
 * Prefers `shortName` so labels stay compact in chips and dropdowns;
 * falls back to `name`. Use this once per render pass to keep all
 * person-headline calls consistent.
 */
export function buildOrgDisplayLookup(orgs) {
    const map = new Map();
    for (const org of orgs) {
        const display = org.data.shortName ?? org.data.name;
        if (display)
            map.set(org.id, display);
    }
    return (id) => map.get(id);
}
/**
 * Rotates the affiliations list so the home-org affiliation is first, when
 * present. The relative order of other affiliations is preserved. Use this
 * for rendering affiliation lists on a given site without mutating the
 * authored order in the source MDX.
 */
export function sortAffiliationsForSite(affiliations, homeOrgId) {
    if (!affiliations?.length)
        return [];
    if (!homeOrgId)
        return affiliations.slice();
    const homeIndex = affiliations.findIndex((aff) => aff.organizationId === homeOrgId);
    if (homeIndex < 0)
        return affiliations.slice();
    const head = affiliations[homeIndex];
    return [head, ...affiliations.filter((_, i) => i !== homeIndex)];
}
export function toCurrentAffiliation(affiliation, partnerName) {
    if (!affiliation?.organizationId || !affiliation.role) {
        return undefined;
    }
    return {
        organizationId: affiliation.organizationId,
        partnerName,
        role: affiliation.role,
    };
}
export function toOrganizationKeyContact(params) {
    const { personEntry, organizationId, partnerName } = params;
    const affiliation = personEntry.data.affiliations?.find((aff) => aff.organizationId === organizationId);
    return {
        personId: personEntry.id,
        person: personEntry.data,
        role: affiliation?.role,
        department: affiliation?.department,
        currentAffiliation: toCurrentAffiliation(affiliation, partnerName ?? personEntry.data.name),
    };
}
export function toResearchAuthor(contributor, personEntry) {
    return {
        ...contributor,
        person: toPersonListData(personEntry),
    };
}
function isPersonEntryLike(value) {
    return typeof value.id === "string";
}
function toDate(value) {
    if (value instanceof Date)
        return Number.isNaN(value.getTime()) ? undefined : value;
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? undefined : date;
}
